"""
Detect NVIDIA GPU and ensure CUDA runtime libs for CTranslate2 / faster-whisper /
onnxruntime-gpu (WhisperSeg).

CTranslate2 Windows wheels target CUDA 12 (`cublas64_12.dll`). Users often only have
the NVIDIA driver (nvidia-smi works) without the CUDA Toolkit on PATH. We install the
official pip wheels (`nvidia-cublas-cu12`, …) into the engine venv and prepend their
`bin` dirs to PATH.

onnxruntime-gpu is selected by driver CUDA major:
  CUDA 12 → ``onnxruntime-gpu>=1.21,<1.27``
  CUDA 13 → ``onnxruntime-gpu>=1.27`` (+ nvidia-*-cu13 extras)
"""

from __future__ import annotations

import logging
import os
import re
import subprocess
import sys
import threading
import time
