from typing import Any, Callable

from .device import (
    ctranslate2_cuda_status,
    ctranslate2_cuda_usable,
    detect_device,
    ensure_cublas12_on_path,
    find_cublas64_12,
    find_cublas64_13,
)

ProgressCb = Callable[[dict[str, Any]], None]

