# Official PyPI defaults (ORT docs, 2026):
#   CUDA 13.x → onnxruntime-gpu >= 1.27
#   CUDA 12.x → onnxruntime-gpu 1.21–1.26 (built with CUDA 12.8)
ORT_GPU_BY_CUDA: dict[str, dict[str, Any]] = {
    "cuda13": {
        "target": "cuda13",
        "requirement": "onnxruntime-gpu>=1.27",
        "min_driver_major": 13,
        "pip_packages": CUDA13_PIP_PACKAGES,
        "label": "CUDA 13",
    },
    "cuda12": {
        "target": "cuda12",
        "requirement": "onnxruntime-gpu>=1.21,<1.27",
        "min_driver_major": 12,
        "pip_packages": (),  # covered by CUDA12_PIP_PACKAGES (CT2 stack)
        "label": "CUDA 12",
    },
}

