# Minimum driver-reported CUDA capability for CUDA 12 userspace libs.
MIN_DRIVER_CUDA_MAJOR = 12


_RE_NVIDIA_SMI_CUDA = re.compile(
    # Classic:  CUDA Version: 12.6
    # Newer R610+: CUDA UMD Version: 13.3
    r"CUDA\s+(?:UMD\s+)?Version:\s*([\d.]+)",
    re.I,
)


def _parse_driver_cuda_version_from_text(text: str) -> str:
    """Extract driver CUDA capability from nvidia-smi (or similar) text."""
    for line in str(text or "").splitlines():
        m = _RE_NVIDIA_SMI_CUDA.search(line)
        if m:
            return str(m.group(1) or "").strip()
    return ""


def _parse_cuda_toolkit_version() -> str:
    """Best-effort CUDA Toolkit major.minor from env / Program Files."""
    candidates: list[str] = []
    for key in (
        "CUDA_PATH",
        "CUDA_PATH_V13_3",
        "CUDA_PATH_V13_2",
        "CUDA_PATH_V13_1",
        "CUDA_PATH_V13_0",
        "CUDA_PATH_V12_9",
        "CUDA_PATH_V12_8",
        "CUDA_PATH_V12_6",
        "CUDA_PATH_V12_4",
        "CUDA_PATH_V12_1",
        "CUDA_PATH_V12_0",
    ):
        root = str(os.environ.get(key) or "").strip()
        if not root:
            continue
        name = Path(root).name  # e.g. v13.3
        m = re.search(r"v?(\d+)\.(\d+)", name, re.I)
        if m:
            candidates.append(f"{m.group(1)}.{m.group(2)}")
    if os.name == "nt":
        base = Path(r"C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA")
        if base.is_dir():
            for child in base.iterdir():
                if not child.is_dir():
                    continue
                m = re.search(r"v?(\d+)\.(\d+)", child.name, re.I)
                if m:
                    candidates.append(f"{m.group(1)}.{m.group(2)}")
    if not candidates:
        return ""
    # Prefer the newest toolkit version found.
    def _key(ver: str) -> tuple[int, int]:
        parts = str(ver).split(".")
        try:
            return (int(parts[0]), int(parts[1]) if len(parts) > 1 else 0)
        except Exception:
            return (0, 0)

    return sorted(candidates, key=_key)[-1]


def _parse_driver_cuda_version() -> str:
    """
    Parse max CUDA version supported by the driver / toolkit.

    Prefers ``nvidia-smi`` banner (classic ``CUDA Version`` or newer
    ``CUDA UMD Version``), then falls back to installed CUDA Toolkit paths.
    """
    try:
        out = subprocess.check_output(
            ["nvidia-smi"],
            text=True,
            timeout=8,
            stderr=subprocess.DEVNULL,
            encoding="utf-8",
            errors="replace",
        )
        parsed = _parse_driver_cuda_version_from_text(out)
        if parsed:
            return parsed
    except Exception:
        pass
    return _parse_cuda_toolkit_version()


def _major_version(ver: str) -> int:
    try:
        return int(str(ver or "").strip().split(".")[0])
    except Exception:
        return 0


def resolve_ort_gpu_cuda_target(
    driver_cuda: str = "",
    *,
    has_cublas12: bool | None = None,
    has_cublas13: bool | None = None,
    prefer_driver: bool = False,
) -> str | None:
    """
    Pick onnxruntime-gpu CUDA major: ``cuda12``, ``cuda13``, or None.

    Planning installs should pass ``prefer_driver=True`` so a CUDA 13-capable
    driver is not forced down to CUDA 12 just because CT2's cu12 libs are present.
    Validation / hints may omit that flag to prefer whichever userspace exists.
    """
    major = _major_version(driver_cuda)
    if has_cublas12 is None:
        has_cublas12 = bool(find_cublas64_12())
    if has_cublas13 is None:
        has_cublas13 = bool(find_cublas64_13())

    if prefer_driver:
        if major >= 13:
            return "cuda13"
        if major >= 12 or major == 0:
            return "cuda12"
        return None

    # Userspace-only signal when majors disagree (avoid ABI mismatch).
    if has_cublas13 and not has_cublas12:
        return "cuda13"
    if has_cublas12 and not has_cublas13:
        return "cuda12"
    if has_cublas12 and has_cublas13:
        if major >= 13:
            return "cuda13"
        return "cuda12"

    if major >= 13:
        return "cuda13"
    if major >= 12 or major == 0:
        return "cuda12"
    return None


def ort_gpu_spec_for_target(target: str | None) -> dict[str, Any] | None:
    """Return requirement / nvidia packages for a CUDA target, or None."""
    key = str(target or "").strip().lower()
    spec = ORT_GPU_BY_CUDA.get(key)
    return dict(spec) if spec else None


def resolve_ort_gpu_spec(
    driver_cuda: str = "",
    *,
    prefer_driver: bool = False,
) -> dict[str, Any] | None:
    """Resolve onnxruntime-gpu pin for the current machine."""
    target = resolve_ort_gpu_cuda_target(driver_cuda, prefer_driver=prefer_driver)
    return ort_gpu_spec_for_target(target)


def ort_gpu_install_hint(driver_cuda: str = "") -> str:
    """Human-readable pip hint for the matching onnxruntime-gpu wheel."""
    driver = driver_cuda or _parse_driver_cuda_version()
    spec = resolve_ort_gpu_spec(driver, prefer_driver=True)
    if not spec:
        return (
            "当前驱动 CUDA 能力不足，无法使用 onnxruntime-gpu；"
            "请升级 NVIDIA 驱动至支持 CUDA 12+。"
        )
    req = str(spec.get("requirement") or "onnxruntime-gpu")
    label = str(spec.get("label") or spec.get("target") or "")
    extra = ""
    pkgs = tuple(spec.get("pip_packages") or ())
    if pkgs:
        extra = f" 及 {' / '.join(pkgs[:3])}{'…' if len(pkgs) > 3 else ''}"
    elif str(spec.get("target")) == "cuda12":
        extra = " 及 nvidia-cublas/cudnn/cufft/curand-cu12"
    return f"安装 {label} 兼容的 {req}{extra}"


def _ort_gpu_version_installed() -> str:
    try:
        from importlib.metadata import PackageNotFoundError, version

        try:
            return str(version("onnxruntime-gpu") or "")
        except PackageNotFoundError:
            return ""
    except Exception:
        return ""


def _ort_gpu_requirement_satisfied(requirement: str) -> bool:
    """True when onnxruntime-gpu is installed and matches the version pin."""
    text = str(requirement or "").strip()
    if not text:
        return False
    try:
        from importlib.metadata import PackageNotFoundError, version
        from packaging.requirements import Requirement

        req = Requirement(text)
        try:
            installed = version(req.name)
        except PackageNotFoundError:
            return False
        if req.specifier and installed not in req.specifier:
            return False
        return True
    except Exception:
        return False


def _ort_gpu_compatible_targets(
    driver_cuda: str = "",
    *,
    has_cublas12: bool | None = None,
    has_cublas13: bool | None = None,
) -> list[str]:
    """
    Ordered CUDA targets whose onnxruntime-gpu pin can work on this machine.

    Driver CUDA N is backward-compatible with userspace CUDA N-1. A CUDA 13
    driver with only cu12 libs can still run onnxruntime-gpu 1.21.x; requiring
    >=1.27 solely because nvidia-smi says 13.x leaves a working stack as
    "partial" forever and one-click repair cannot clear the warning.
    """
    if has_cublas12 is None:
        has_cublas12 = bool(find_cublas64_12())
    if has_cublas13 is None:
        has_cublas13 = bool(find_cublas64_13())

    preferred = resolve_ort_gpu_cuda_target(
        driver_cuda,
        has_cublas12=has_cublas12,
        has_cublas13=has_cublas13,
        prefer_driver=True,
    )
    userspace = resolve_ort_gpu_cuda_target(
        driver_cuda,
        has_cublas12=has_cublas12,
        has_cublas13=has_cublas13,
        prefer_driver=False,
    )
    ordered: list[str] = []
    for target in (preferred, userspace, "cuda12" if has_cublas12 else "", "cuda13" if has_cublas13 else ""):
        key = str(target or "").strip().lower()
        if key and key in ORT_GPU_BY_CUDA and key not in ordered:
            ordered.append(key)
    return ordered


def resolve_ort_gpu_readiness(
    driver_cuda: str = "",
    *,
    has_cublas12: bool | None = None,
    has_cublas13: bool | None = None,
) -> dict[str, Any]:
    """
    Decide whether WhisperSeg onnxruntime-gpu is ready.

    Ready when any userspace-compatible pin is satisfied (not only the
    driver-preferred CUDA 13 wheel). ``desiredTarget`` / ``desiredRequirement``
    still reflect prefer_driver for install hints and force upgrades.
    """
    if has_cublas12 is None:
        has_cublas12 = bool(find_cublas64_12())
    if has_cublas13 is None:
        has_cublas13 = bool(find_cublas64_13())
    driver = driver_cuda or _parse_driver_cuda_version()
    desired = resolve_ort_gpu_cuda_target(
        driver,
        has_cublas12=has_cublas12,
        has_cublas13=has_cublas13,
        prefer_driver=True,
    )
    desired_spec = ort_gpu_spec_for_target(desired)
    desired_req = str((desired_spec or {}).get("requirement") or "")

    for target in _ort_gpu_compatible_targets(
        driver,
        has_cublas12=has_cublas12,
        has_cublas13=has_cublas13,
    ):
        spec = ort_gpu_spec_for_target(target)
        req = str((spec or {}).get("requirement") or "")
        if req and _ort_gpu_requirement_satisfied(req):
            return {
                "ok": True,
                "target": target,
                "requirement": req,
                "desiredTarget": desired or "",
                "desiredRequirement": desired_req,
                "version": _ort_gpu_version_installed(),
            }

    return {
        "ok": False,
        "target": desired or "",
        "requirement": desired_req,
        "desiredTarget": desired or "",
        "desiredRequirement": desired_req,
        "version": _ort_gpu_version_installed(),
    }


def _cuda_ep_available() -> bool:
    try:
        inject_nvidia_lib_path()
        import onnxruntime as ort  # type: ignore

        try:
            preload = getattr(ort, "preload_dlls", None)
            if callable(preload):
                preload()
        except Exception:
            pass
        return "CUDAExecutionProvider" in list(ort.get_available_providers() or [])
    except Exception:
        return False


def probe_gpu_runtime() -> dict[str, Any]:
    """
    Summarize GPU + CUDA runtime readiness for Whisper/CT2 / WhisperSeg ORT.
    """
    # Inject before any CT2/ORT import so Windows can resolve CUDA DLLs.
    try:
        inject_nvidia_lib_path()
    except Exception:
        pass
    device = detect_device()
    driver_cuda = _parse_driver_cuda_version()
    cublas = find_cublas64_12()
    cublas13 = find_cublas64_13()
    # Never import ctranslate2 here — LoadLibrary of CUDA / CT2 DLLs under
    # Smart App Control can hang the engine thread pool and freeze model refresh.
    ct2_status = ctranslate2_cuda_status(live=False)
    ct2_ok = bool(ct2_status.get("ok"))
    has_cuda = bool(device.get("hasCuda"))
    driver_major = _major_version(driver_cuda)
    # CUDA 12 userspace needs a driver that advertises >= 12.
    driver_ok = (not has_cuda) or driver_major == 0 or driver_major >= MIN_DRIVER_CUDA_MAJOR
    missing = list(CUDA12_PIP_PACKAGES) if (has_cuda and driver_ok and not cublas) else []
    ort_ready = resolve_ort_gpu_readiness(
        driver_cuda,
        has_cublas12=bool(cublas),
        has_cublas13=bool(cublas13),
    )
    ort_ok = bool(ort_ready.get("ok"))
    ort_target = str(ort_ready.get("target") or "")
    # Install / force-upgrade hint still prefers the driver-max wheel.
    ort_req = str(
        ort_ready.get("desiredRequirement")
        or ort_ready.get("requirement")
        or ""
    )
    desired_target = str(ort_ready.get("desiredTarget") or ort_target or "")
    desired_spec = ort_gpu_spec_for_target(desired_target)
    # Only list CUDA 13 nvidia-* as missing when ORT is not already satisfied
    # via a compatible lower pin (e.g. 1.21.x + cu12 on a CUDA 13 driver).
    if (
        has_cuda
        and driver_ok
        and not ort_ok
        and desired_spec
        and str(desired_spec.get("target")) == "cuda13"
        and not cublas13
    ):
        for pkg in desired_spec.get("pip_packages") or ():
            if pkg not in missing:
                missing.append(pkg)
    # ASR/CT2 and WhisperSeg ORT are separate stacks; "ready" means both when ORT applies.
    asr_ok = bool(cublas and ct2_ok)
    ort_needed = bool(has_cuda and driver_ok and (ort_req or desired_target))
    ort_stack_ok = (not ort_needed) or ort_ok
    if has_cuda and not driver_ok:
        status = "driver_too_old"
    elif not has_cuda:
        status = "no_gpu"
    elif asr_ok and ort_stack_ok:
        status = "ready"
    elif cublas and (not asr_ok or not ort_stack_ok):
        status = "partial"
    else:
        status = "need_install"

    # Surface the satisfied pin when ready; otherwise the desired install pin.
    report_req = (
        str(ort_ready.get("requirement") or ort_req)
        if ort_ok
        else ort_req
    )

    return {
        "ok": True,
        "status": status,
        "hasCuda": has_cuda,
        "gpuName": device.get("gpuName") or "",
        "vramMb": int(device.get("vramMb") or 0),
        "driverCudaVersion": driver_cuda,
        "cublas12": bool(cublas),
        "cublas13": bool(cublas13),
        "cublasPath": cublas or "",
        "cublas13Path": cublas13 or "",
        "ctranslate2Cuda": bool(ct2_ok),
        "ctranslate2CudaReason": str(ct2_status.get("reason") or ""),
        "ctranslate2DeviceCount": int(ct2_status.get("deviceCount") or 0),
        "asrGpuReady": bool(asr_ok),
        "target": "cuda12",
        "ortGpuTarget": ort_target or desired_target,
        "ortGpuDesiredTarget": desired_target,
        "ortGpuRequirement": report_req,
        "ortGpuVersion": _ort_gpu_version_installed(),
        "ortGpuCuda": bool(ort_ok),
        # Alias for UI: WhisperSeg GPU == onnxruntime-gpu pin satisfied for this machine.
        "whispersegGpuReady": bool(ort_ok),
        "packages": list(CUDA12_PIP_PACKAGES),
        "missingPackages": missing,
        "device": device,
        "hint": _status_hint(
            status,
            device.get("gpuName") or "",
            driver_cuda,
            ct2_ok=bool(ct2_ok),
            ort_ok=bool(ort_ok),
            ort_needed=ort_needed,
            ort_req=report_req,
            ct2_reason=str(ct2_status.get("reason") or ""),
        ),
    }


def _status_hint(
    status: str,
    gpu_name: str,
    driver_cuda: str,
    *,
    ct2_ok: bool = False,
    ort_ok: bool = False,
    ort_needed: bool = False,
    ort_req: str = "",
    ct2_reason: str = "",
) -> str:
    """
    Human-readable GPU readiness. ASR/CTranslate2 and WhisperSeg (onnxruntime-gpu)
    are separate backends — do not claim full readiness when only one stack is OK.
    """
    if status == "ready":
        stacks = "ASR/CTranslate2"
        if ort_needed:
            stacks += " + WhisperSeg ONNX"
        return (
            f"GPU 运行库已就绪（{stacks}；"
            f"{gpu_name or 'NVIDIA'}，驱动 CUDA {driver_cuda or '?'}）"
        )
    if status == "no_gpu":
        return "未检测到 NVIDIA GPU，将使用 CPU"
    if status == "driver_too_old":
        return (
            f"显卡驱动 CUDA 能力为 {driver_cuda or '?'}，低于 12。"
            "请升级 NVIDIA 驱动后再安装 CUDA 12 运行库。"
        )
    if status == "need_install":
        return (
            f"已检测到 {gpu_name or 'NVIDIA GPU'}，但缺少 cublas64_12.dll。"
            "可一键下载 CUDA 12 支持组件（nvidia-cublas-cu12 等）。"
        )
    if status == "partial":
        parts: list[str] = []
        if ct2_ok:
            parts.append("ASR/CTranslate2 GPU 已就绪")
        else:
            reason = str(ct2_reason or "").strip()
            if reason == "ctranslate2_not_installed" or "No module named 'ctranslate2'" in reason:
                parts.append(
                    "未安装 CTranslate2（Whisper / Opus-MT 运行库）。"
                    "请在「听写运行库」或系统检查里对 Whisper 运行库点「一键修复」，"
                    "不要只下 GPU 支持"
                )
            else:
                detail = f"（原因：{reason}）" if reason else ""
                parts.append(
                    "已找到 cuBLAS，但 CTranslate2 仍无法使用 CUDA"
                    f"{detail}；可重新下载 GPU 支持，或检查显卡驱动"
                )
        if ort_needed and not ort_ok:
            req = str(ort_req or "onnxruntime-gpu").strip() or "onnxruntime-gpu"
            parts.append(
                "WhisperSeg（onnxruntime-gpu）未就绪，灵敏检出将回退 CPU；"
                f"请再次「下载 GPU 支持」或手动安装（{req}）"
            )
        elif ort_needed and ort_ok and not ct2_ok:
            parts.append("WhisperSeg ONNX GPU 已就绪")
        return "；".join(parts)
    return ""


def _pip_list_installed(names: tuple[str, ...]) -> set[str]:
    want = {n.lower() for n in names}
    found: set[str] = set()
    try:
        out = subprocess.check_output(
            [sys.executable, "-m", "pip", "list", "--format=freeze"],
            text=True,
            timeout=120,
            stderr=subprocess.DEVNULL,
            encoding="utf-8",
            errors="replace",
        )
    except Exception:
        return found
    for line in (out or "").splitlines():
        pkg = line.split("==", 1)[0].strip().lower()
        if pkg in want:
            found.add(pkg)
    return found


def _nvidia_bin_dirs() -> list[str]:
    """site-packages/nvidia/*/bin directories that may contain CUDA DLLs."""
    dirs: list[str] = []
    try:
        import site

        roots = list(site.getsitepackages() or [])
        user = site.getusersitepackages()
        if user:
            roots.append(user)
    except Exception:
        roots = []
    # Also walk relative to this interpreter
    roots.append(str(Path(sys.prefix) / "Lib" / "site-packages"))
    roots.append(str(Path(sys.prefix) / "lib" / "site-packages"))
    seen: set[str] = set()
    for root in roots:
        base = Path(root) / "nvidia"
        if not base.is_dir():
            continue
        for child in base.iterdir():
            for sub in ("bin", "lib", "lib/x64"):
                candidate = child / sub
                try:
                    key = str(candidate.resolve()).lower()
                except Exception:
                    key = str(candidate).lower()
                if key in seen or not candidate.is_dir():
                    continue
                seen.add(key)
                dirs.append(str(candidate.resolve()))
    return dirs


def _torch_lib_dirs() -> list[str]:
    """
    Optional fallback: torch ships cufft/curand next to its CUDA libs.

    Used when nvidia-cufft-cu12 / nvidia-curand-cu12 are not installed yet so
    onnxruntime-gpu can still load CUDAExecutionProvider.

    Filesystem only — do not import torch (CUDA DLL load can freeze Windows).
    """
    dirs: list[str] = []
    py = f"python{sys.version_info.major}.{sys.version_info.minor}"
    for candidate in (
        Path(sys.prefix) / "Lib" / "site-packages" / "torch" / "lib",
        Path(sys.prefix) / "lib" / py / "site-packages" / "torch" / "lib",
    ):
        if candidate.is_dir():
            dirs.append(str(candidate.resolve()))
    return dirs


def inject_nvidia_lib_path() -> list[str]:
    """Prepend nvidia wheel bin dirs (+ optional torch/lib) to PATH.

    nvidia-* bins must stay ahead of ``torch\\\\lib``: torch ships its own
    ``cublas64_12.dll``, and CTranslate2 often fails to load it (WinError 999 /
    \"cannot be loaded\") when that copy shadows the nvidia-cublas wheel.
    torch/lib remains on PATH only as a lower-priority fallback for ORT
    cufft/curand when the matching nvidia-* wheels are absent.
    """
    added: list[str] = []
    nvidia = list(_nvidia_bin_dirs())
    torch_libs = _torch_lib_dirs()
    managed = {d.lower() for d in nvidia + torch_libs}

    path_env = os.environ.get("PATH", "")
    rest = [p for p in path_env.split(os.pathsep) if p and p.lower() not in managed]

    # Relative order: all nvidia bins first, then torch/lib.
    prepend: list[str] = []
    seen: set[str] = set()
    for directory in nvidia + torch_libs:
        key = directory.lower()
        if key in seen:
            continue
        seen.add(key)
        prepend.append(directory)
        added.append(directory)

    os.environ["PATH"] = os.pathsep.join(prepend + rest) if prepend else os.pathsep.join(rest)

    ensure_cublas12_on_path()
    # Clear cached DLL lookup so subsequent probes see new PATH/wheels.
    try:
        find_cublas64_12.cache_clear()
    except Exception:
        pass
    try:
        find_cublas64_13.cache_clear()
    except Exception:
        pass
    return added


def ensure_onnxruntime_gpu(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
    driver_cuda: str = "",
) -> dict[str, Any]:
    """
    Install onnxruntime-gpu pinned to the machine's CUDA major (12 or 13).

    Mutually exclusive with the CPU ``onnxruntime`` wheel. Safe no-op when any
    userspace-compatible GPU wheel is already present (unless ``force``).
    On CUDA 13 drivers that only have CT2's cu12 libs, prefer the CUDA 13 wheel
    but fall back to CUDA 12 ORT when cu13 packages / ORT 1.27+ cannot install.
    """
    def progress(ev: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(ev)
            except Exception:
                pass

    driver = driver_cuda or _parse_driver_cuda_version()
    readiness = resolve_ort_gpu_readiness(driver)
    # Prefer driver-max wheel for fresh installs / force; accept any compatible
    # pin when already present so CUDA 13 drivers keep working CUDA 12 ORT.
    if not force and readiness.get("ok"):
        inject_nvidia_lib_path()
        target = str(readiness.get("target") or "")
        requirement = str(readiness.get("requirement") or "")
        label = str((ort_gpu_spec_for_target(target) or {}).get("label") or target)
        return {
            "ok": True,
            "skipped": True,
            "reason": "already_satisfied",
            "target": target,
            "requirement": requirement,
            "desiredTarget": str(readiness.get("desiredTarget") or ""),
            "version": _ort_gpu_version_installed(),
            "cudaEp": _cuda_ep_available(),
            "message": f"onnxruntime-gpu 已满足 {label}（{requirement}）",
        }

    preferred = resolve_ort_gpu_spec(driver, prefer_driver=True)
    if not preferred:
        return {
            "ok": False,
            "skipped": True,
            "reason": "driver_too_old",
            "message": ort_gpu_install_hint(driver),
        }

    specs: list[dict[str, Any]] = [preferred]
    # Soft fallback: cu12 ORT works with existing CT2 CUDA 12 wheels when the
    # driver prefers CUDA 13 but cu13 nvidia-* / ORT>=1.27 cannot be installed.
    if (
        str(preferred.get("target")) == "cuda13"
        and bool(find_cublas64_12())
        and not bool(find_cublas64_13())
    ):
        fb = ort_gpu_spec_for_target("cuda12")
        if fb:
            specs.append(fb)

    last_fail: dict[str, Any] = {}
    for idx, spec in enumerate(specs):
        requirement = str(spec.get("requirement") or "")
        target = str(spec.get("target") or "")
        label = str(spec.get("label") or target)
        extra_pkgs = [str(p) for p in (spec.get("pip_packages") or ()) if str(p).strip()]
        is_fallback = idx > 0

        if not force and _ort_gpu_requirement_satisfied(requirement):
            inject_nvidia_lib_path()
            return {
                "ok": True,
                "skipped": True,
                "reason": "already_satisfied",
                "target": target,
                "requirement": requirement,
                "version": _ort_gpu_version_installed(),
                "cudaEp": _cuda_ep_available(),
                "message": f"onnxruntime-gpu 已满足 {label}（{requirement}）",
            }

        progress(
            {
                "type": "progress",
                "stage": "ort-gpu",
                "percent": 88 if not is_fallback else 90,
                "detail": (
                    f"正在安装 {label} 版 onnxruntime-gpu（{requirement}）…"
                    if not is_fallback
                    else f"CUDA 13 组件不可用，回退安装 {label} 版 onnxruntime-gpu（{requirement}）…"
                ),
                "target": target,
                "requirement": requirement,
            }
        )

        if extra_pkgs:
            installed_extra = _pip_list_installed(tuple(extra_pkgs))
            to_extra = [p for p in extra_pkgs if force or p.lower() not in installed_extra]
            if to_extra:
                progress(
                    {
                        "type": "progress",
                        "stage": "ort-gpu",
                        "percent": 86,
                        "detail": f"正在安装 {label} 运行库：{', '.join(to_extra)}",
                        "packages": to_extra,
                    }
                )
                pip_extra = _pip_install_cuda_packages(to_extra, progress=progress)
                if not pip_extra.get("ok"):
                    last_fail = {
                        "ok": False,
                        "code": pip_extra.get("code") or "ORT_GPU_CUDA_LIBS_FAILED",
                        "message": pip_extra.get("message")
                        or f"安装 {label} nvidia 运行库失败",
                        "detail": pip_extra.get("detail") or "",
                        "target": target,
                        "requirement": requirement,
                    }
                    if idx + 1 < len(specs):
                        progress(
                            {
                                "type": "progress",
                                "stage": "ort-gpu",
                                "percent": 87,
                                "detail": (
                                    f"{label} 运行库安装失败，尝试兼容的下一档 onnxruntime-gpu…"
                                ),
                            }
                        )
                        continue
                    return last_fail

        try:
            from .runtime_extras import (
                _install_packages,
                _uninstall_onnxruntime_cpu_if_present,
            )
        except Exception as err:
            return {
                "ok": False,
                "code": "ORT_GPU_INSTALL_UNAVAILABLE",
                "message": f"无法加载 pip 安装辅助：{err}",
                "target": target,
                "requirement": requirement,
            }

        try:
            _uninstall_onnxruntime_cpu_if_present()
        except Exception as err:
            _log.warning("onnxruntime CPU uninstall failed: %s", err)

        result = _install_packages(
            (requirement,),
            force=force,
            on_progress=on_progress,
            label=" onnxruntime-gpu",
        )
        if not result.get("ok"):
            last_fail = {
                **result,
                "target": target,
                "requirement": requirement,
                "code": result.get("code") or "ORT_GPU_INSTALL_FAILED",
            }
            if idx + 1 < len(specs):
                progress(
                    {
                        "type": "progress",
                        "stage": "ort-gpu",
                        "percent": 89,
                        "detail": (
                            f"{label} onnxruntime-gpu 安装失败，尝试兼容的下一档…"
                        ),
                    }
                )
                continue
            return last_fail

        inject_nvidia_lib_path()
        try:
            find_cublas64_12.cache_clear()
            find_cublas64_13.cache_clear()
        except Exception:
            pass

        ok = _ort_gpu_requirement_satisfied(requirement)
        if not ok:
            # Accept any other compatible pin that became satisfied.
            after = resolve_ort_gpu_readiness(driver)
            ok = bool(after.get("ok"))
            if ok:
                target = str(after.get("target") or target)
                requirement = str(after.get("requirement") or requirement)
                label = str((ort_gpu_spec_for_target(target) or {}).get("label") or label)

        cuda_ep = _cuda_ep_available() if ok else False
        progress(
            {
                "type": "done" if ok else "error",
                "stage": "ort-gpu",
                "percent": 96,
                "detail": (
                    f"onnxruntime-gpu {label} 已就绪"
                    + ("（CUDA EP 可用）" if cuda_ep else "（已安装，CUDA EP 待重启后确认）")
                    if ok
                    else f"已尝试安装但未满足 {requirement}"
                ),
                "target": target,
            }
        )
        return {
            "ok": ok,
            "skipped": bool(result.get("skipped")),
            "target": target,
            "requirement": requirement,
            "fallback": is_fallback,
            "version": _ort_gpu_version_installed(),
            "cudaEp": cuda_ep,
            "installed": result.get("installed") or [],
            "mirror": result.get("mirror") or "",
            "message": (
                f"onnxruntime-gpu {label} 已安装（{requirement}）"
                if ok
                else f"安装后仍未满足 {requirement}"
            ),
        }

    return last_fail or {
        "ok": False,
        "code": "ORT_GPU_INSTALL_FAILED",
        "message": "onnxruntime-gpu 安装失败",
    }


def _dir_nbytes(path: Path) -> int:
    total = 0
    try:
        if not path.exists():
            return 0
        for root, _dirs, files in os.walk(path):
            for name in files:
                try:
                    total += (Path(root) / name).stat().st_size
                except OSError:
                    continue
    except OSError:
        return total
    return total


def _pip_cache_roots() -> list[Path]:
    """
    Temporary pip dirs that may hold in-flight wheels.

    Used only as a weak fallback when pip text has no byte counters yet.
    Do NOT sum these with site-packages — the same bytes land in both places.
    """
    roots: list[Path] = []
    try:
        import tempfile

        tmp = Path(tempfile.gettempdir())
        if tmp.is_dir():
            for child in tmp.iterdir():
                name = str(child.name or "").lower()
                if child.is_dir() and (
                    name.startswith("pip-")
                    or name.startswith("pip_")
                    or "pip-unpack" in name
                    or "pip-ephem" in name
                    or "pip-install" in name
                    or "pip-wheel" in name
                    or "pip-download" in name
                ):
                    roots.append(child)
    except Exception:
        pass
    return roots


def _refresh_pip_watch_roots(nvidia_root: Path, known: list[Path]) -> list[Path]:
    """Rebuild watch list so newly created pip-unpack dirs are included."""
    roots = [nvidia_root, *_pip_cache_roots()]
    for old in known:
        if old not in roots:
            roots.append(old)
    return roots


def _ensure_ctranslate2_alongside_gpu(
    *,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any] | None:
    """
    GPU wheels can be present while Whisper's ctranslate2 is still missing
    (faster-whisper often installs with --no-deps). Pull CT2 in the same pass
    so one-click 「下载 GPU 支持」actually clears the gpuRuntime CT2 warn.
    """
    probe = probe_gpu_runtime()
    if probe.get("ctranslate2Cuda"):
        return None
    reason = str(probe.get("ctranslate2CudaReason") or "")
    missing = reason == "ctranslate2_not_installed"
    if not missing:
        try:
            import ctranslate2  # noqa: F401
        except ModuleNotFoundError:
            missing = True
        except Exception:
            return None
    if not missing:
        return None
    if on_progress:
        try:
            on_progress(
                {
                    "type": "progress",
                    "stage": "whisper_runtime",
                    "percent": 90,
                    "detail": "检测到缺少 CTranslate2，正在补齐 Whisper 运行库…",
                }
            )
        except Exception:
            pass
    try:
        from .runtime_extras import ensure_asr_whisper

        return ensure_asr_whisper(force=False, on_progress=on_progress)
    except Exception as err:
        return {"ok": False, "message": str(err)}


def ensure_gpu_runtime(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """
    Auto-detect GPU and install CUDA 12 pip wheels when needed.

    Returns a result dict with status / installed packages / probe after install.
    """
    def progress(ev: dict[str, Any]) -> None:
        if on_progress:
            on_progress(ev)

    probe = probe_gpu_runtime()
    progress(
        {
            "type": "progress",
            "stage": "probe",
            "percent": 5,
            "detail": probe.get("hint") or "检测 GPU…",
            "probe": probe,
        }
    )

    if probe["status"] == "no_gpu":
        return {
            "ok": True,
            "skipped": True,
            "reason": "no_gpu",
            "probe": probe,
            "message": probe.get("hint"),
        }
    if probe["status"] == "driver_too_old":
        return {
            "ok": False,
            "code": "DRIVER_TOO_OLD",
            "probe": probe,
            "message": probe.get("hint"),
        }
    if probe["status"] == "ready" and not force:
        inject_nvidia_lib_path()
        ort_result = ensure_onnxruntime_gpu(
            force=False,
            on_progress=on_progress,
            driver_cuda=str(probe.get("driverCudaVersion") or ""),
        )
        whisper_fix = _ensure_ctranslate2_alongside_gpu(on_progress=on_progress)
        after = probe_gpu_runtime()
        return {
            "ok": after.get("status") == "ready",
            "skipped": bool(ort_result.get("skipped")) and not whisper_fix,
            "reason": "already_ready",
            "probe": after,
            "ortGpu": ort_result,
            "whisperRuntime": whisper_fix,
            "message": (after.get("hint") or "")
            + (
                f"；{ort_result.get('message')}"
                if ort_result.get("message") and not ort_result.get("skipped")
                else ""
            ),
        }

    packages = list(CUDA12_PIP_PACKAGES)
    progress(
        {
            "type": "progress",
            "stage": "probe",
            "percent": 10,
            "detail": "检查已安装的 CUDA 组件…",
        }
    )
    installed = _pip_list_installed(tuple(packages))
    to_install = [p for p in packages if force or p.lower() not in installed]
    # Even if pip packages are present, DLL may be missing from PATH — still inject.
    if not to_install and probe.get("cublas12") and not force:
        inject_nvidia_lib_path()
        ort_result = ensure_onnxruntime_gpu(
            force=False,
            on_progress=on_progress,
            driver_cuda=str(probe.get("driverCudaVersion") or ""),
        )
        whisper_fix = _ensure_ctranslate2_alongside_gpu(on_progress=on_progress)
        after = probe_gpu_runtime()
        ort_needed = bool(after.get("ortGpuRequirement") or after.get("ortGpuDesiredTarget"))
        ort_ok = (not ort_needed) or bool(after.get("ortGpuCuda"))
        ct2_missing = str(after.get("ctranslate2CudaReason") or "") == "ctranslate2_not_installed"
        ok = bool(after.get("cublas12")) and ort_ok and not ct2_missing
        return {
            "ok": ok,
            "skipped": bool(ort_result.get("skipped")) and not whisper_fix,
            "reason": "packages_present",
            "probe": after,
            "ortGpu": ort_result,
            "whisperRuntime": whisper_fix,
            "message": (after.get("hint") or "")
            + (
                f"；{ort_result.get('message')}"
                if ort_result.get("message") and not ort_result.get("skipped")
                else ""
            ),
            "installed": [],
        }

    if not to_install:
        to_install = list(packages)

    progress(
        {
            "type": "progress",
            "stage": "download",
            "percent": 15,
            "detail": f"正在安装 GPU 支持：{', '.join(to_install)}（国内镜像，约数百 MB）",
            "packages": to_install,
        }
    )

    pip_result = _pip_install_cuda_packages(to_install, progress=progress)
    if not pip_result.get("ok"):
        return {
            "ok": False,
            "code": pip_result.get("code") or "GPU_RUNTIME_INSTALL_FAILED",
            "message": pip_result.get("message") or "pip 安装 GPU 支持失败",
            "detail": pip_result.get("detail") or "",
            "probe": probe,
            "packages": to_install,
            "mirror": pip_result.get("mirror") or "",
        }

    progress(
        {
            "type": "progress",
            "stage": "activate",
            "percent": 85,
            "detail": "正在激活 CUDA 运行库 PATH…",
        }
    )
    added = inject_nvidia_lib_path()
    try:
        find_cublas64_12.cache_clear()
        find_cublas64_13.cache_clear()
    except Exception:
        pass

    # Match onnxruntime-gpu to driver CUDA major (12 vs 13). Soft-fail: CT2
    # CUDA libs may still be usable even if ORT GPU install stalls.
    ort_result = ensure_onnxruntime_gpu(
        force=force,
        on_progress=on_progress,
        driver_cuda=str(probe.get("driverCudaVersion") or ""),
    )
    whisper_fix = _ensure_ctranslate2_alongside_gpu(on_progress=on_progress)

    after = probe_gpu_runtime()
    ort_needed = bool(after.get("ortGpuRequirement") or after.get("ortGpuDesiredTarget"))
    ort_ok = (not ort_needed) or bool(after.get("ortGpuCuda"))
    ct2_missing = str(after.get("ctranslate2CudaReason") or "") == "ctranslate2_not_installed"
    ok = (bool(after.get("cublas12")) or bool(after.get("ctranslate2Cuda"))) and ort_ok and not ct2_missing
    ort_note = ""
    if ort_result.get("ok"):
        if not ort_result.get("skipped"):
            ort_note = f"；{ort_result.get('message') or 'onnxruntime-gpu 已安装'}"
    elif not ort_result.get("skipped"):
        ort_note = f"；onnxruntime-gpu 未就绪：{ort_result.get('message') or '安装失败'}"
    if whisper_fix and not whisper_fix.get("ok") and not whisper_fix.get("skipped"):
        ort_note += f"；Whisper 运行库：{whisper_fix.get('message') or '补齐失败'}"
    progress(
        {
            "type": "done" if ok else "error",
            "stage": "done",
            "percent": 100,
            "detail": (
                (after.get("hint") or ("GPU 支持已安装" if ok else "安装完成但仍未就绪"))
                + ort_note
            ),
        }
    )
    return {
        "ok": ok,
        "skipped": False,
        "installed": to_install,
        "pathAdded": added,
        "probe": after,
        "ortGpu": ort_result,
        "whisperRuntime": whisper_fix,
        "mirror": pip_result.get("mirror") or "",
        "message": (
            (after.get("hint") or "") + ort_note
            if ok
            else (
                (
                    "已安装 pip 包，但仍未找到 cublas64_12.dll。"
                    "请重新检测；若仍失败请检查 .venv/Lib/site-packages/nvidia/cublas/bin。"
                )
                if not after.get("cublas12")
                else (
                    (after.get("hint") or "WhisperSeg onnxruntime-gpu 仍未就绪")
                    + ort_note
                )
            )
        ),
        "pipLogTail": str(pip_result.get("logTail") or ""),
    }


def _pip_install_cuda_packages(
    packages: list[str],
    *,
    progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """
    Install CUDA 12 nvidia-* wheels via domestic PyPI mirrors with live progress.

    Prefers resumable direct .whl downloads (ranked by package throughput probe),
    then falls back to ``pip install -i``. Stalls switch mirrors within ~90s.
    """
    def emit(ev: dict[str, Any]) -> None:
        if progress:
            try:
                progress(ev)
            except Exception:
                pass

    def _size_hint(pkg: str) -> int:
        return int(
            CUDA12_SIZE_HINT_BYTES.get(pkg)
            or CUDA13_SIZE_HINT_BYTES.get(pkg)
            or (80 * 1024 * 1024)
        )

    hint_total = sum(_size_hint(p) for p in packages) or (800 * 1024 * 1024)
    last_error = ""
    last_detail = ""

    try:
        from .pip_mirror_util import (
            best_probe_bytes_per_sec,
            download_known_wheels,
            format_bytes_per_sec,
            format_probe_summary,
            install_local_wheel_files,
            is_mirror_http_deny,
            note_mirror_denied,
            order_pip_mirrors,
            probe_pip_mirrors,
        )
    except Exception:
        order_pip_mirrors = None  # type: ignore[assignment]
        probe_pip_mirrors = None  # type: ignore[assignment]
        best_probe_bytes_per_sec = None  # type: ignore[assignment]
        download_known_wheels = None  # type: ignore[assignment]
        format_bytes_per_sec = None  # type: ignore[assignment]
        format_probe_summary = None  # type: ignore[assignment]
        install_local_wheel_files = None  # type: ignore[assignment]
        is_mirror_http_deny = None  # type: ignore[assignment]
        note_mirror_denied = None  # type: ignore[assignment]

    mirrors: list[tuple[str, str]] = list(PYPI_MIRRORS)
    probe_rows: list[dict[str, Any]] = []
    if probe_pip_mirrors and order_pip_mirrors:
        emit(
            {
                "type": "progress",
                "stage": "probe",
                "percent": 12,
                "detail": f"正在测速 PyPI 镜像（索引 + 包文件吞吐，共 {len(PYPI_MIRRORS)} 个）…",
                "totalBytes": hint_total,
            }
        )
        try:
            probe_rows = probe_pip_mirrors(PYPI_MIRRORS)
            mirrors = order_pip_mirrors(probe_rows, mirrors=PYPI_MIRRORS)
        except Exception as probe_err:
            _log.warning("CUDA pip mirror probe failed: %s", probe_err)
            mirrors = list(PYPI_MIRRORS)
        best = mirrors[0][1] if mirrors else ""
        if format_probe_summary:
            probe_summary = format_probe_summary(probe_rows)
        else:
            probe_summary = ", ".join(
                f"{r.get('host')}={'ok' if r.get('ok') else 'fail'}"
                f"{(' ' + str(int(r['latencyMs'])) + 'ms') if r.get('latencyMs') is not None else ''}"
                for r in probe_rows[:4]
            )
        best_bps = best_probe_bytes_per_sec(probe_rows) if best_probe_bytes_per_sec else 0.0
        speed_s = format_bytes_per_sec(best_bps) if format_bytes_per_sec else ""
        suggest = bool(best_bps > 0 and best_bps < 80_000)
        emit(
            {
                "type": "progress",
                "stage": "probe",
                "percent": 15,
                "detail": (
                    f"镜像测速完成，优先使用 {best}"
                    + (f"（约 {speed_s}）" if speed_s else "")
                    + (f"；{probe_summary}" if probe_summary else "")
                    + ("。吞吐较低，若卡住请改用手动下载" if suggest else "")
                ),
                "mirror": mirrors[0][0] if mirrors else "",
                "mirrorProbe": probe_rows,
                "totalBytes": hint_total,
                "suggestManual": suggest,
            }
        )

    direct_attempted = False
    if download_known_wheels:
        direct_attempted = True
        for mirror_url, host in mirrors:
            emit(
                {
                    "type": "progress",
                    "stage": "download",
                    "percent": 18,
                    "detail": f"直链下载 CUDA 组件（{host}，可断点续传）…",
                    "mirror": mirror_url,
                    "totalBytes": hint_total,
                }
            )
            dl = download_known_wheels(
                packages,
                index_url=mirror_url,
                host=host,
                on_progress=progress,
                detail_prefix="下载 GPU 组件",
            )
            if not dl.get("ok"):
                last_error = str(dl.get("error") or f"直链下载失败（{host}）")
                last_detail = last_error
                stalled = bool(dl.get("stalled"))
                if is_mirror_http_deny and is_mirror_http_deny(last_error) and note_mirror_denied:
                    note_mirror_denied(host)
                emit(
                    {
                        "type": "progress",
                        "stage": "download",
                        "percent": 18,
                        "detail": (
                            f"镜像 {host} {'下载停滞' if stalled else '直链失败'}，自动切换下一源…"
                        ),
                        "mirror": mirror_url,
                        "suggestManual": True,
                        "totalBytes": hint_total,
                    }
                )
                continue

            local_paths = list(dl.get("localPaths") or [])
            if not local_paths:
                continue
            # Offline install only — never ``pip install --upgrade <whl>`` without
            # ``--no-index`` (that re-contacts mirrors and often hangs ~10–30 min).
            if install_local_wheel_files:
                inst = install_local_wheel_files(
                    local_paths,
                    on_progress=progress,
                    detail_prefix="安装 GPU 组件",
                    timeout_sec=1800.0,
                )
            else:
                cmd = [
                    sys.executable,
                    "-u",
                    "-m",
                    "pip",
                    "install",
                    "--force-reinstall",
                    "--no-deps",
                    "--no-index",
                    "--no-cache-dir",
                    *local_paths,
                ]
                _log.info("ensure_gpu_runtime local wheels: %s", " ".join(cmd))
                try:
                    proc = subprocess.run(
                        cmd,
                        capture_output=True,
                        text=True,
                        encoding="utf-8",
                        errors="replace",
                        timeout=1800,
                        check=False,
                        env={**os.environ, "PIP_NO_INDEX": "1", "PYTHONUNBUFFERED": "1"},
                    )
                except Exception as err:
                    inst = {"ok": False, "error": str(err)}
                else:
                    inst = {
                        "ok": proc.returncode == 0,
                        "error": f"本地 pip 安装失败（exit {proc.returncode}）",
                        "logTail": ((proc.stdout or "") + (proc.stderr or ""))[-1200:],
                    }

            if inst.get("ok"):
                emit(
                    {
                        "type": "progress",
                        "stage": "download",
                        "percent": 82,
                        "detail": f"镜像 {host} 安装完成",
                        "mirror": mirror_url,
                        "downloadedBytes": hint_total,
                        "totalBytes": hint_total,
                        "bytesPerSecond": 0,
                    }
                )
                return {
                    "ok": True,
                    "mirror": mirror_url,
                    "host": host,
                    "logTail": str(inst.get("logTail") or "")[-500:],
                    "method": "direct-whl",
                }

            # Wheels are already on disk — do not switch mirror and re-download.
            last_error = str(inst.get("error") or "本地安装失败")
            last_detail = str(inst.get("logTail") or last_error)[-1200:]
            return {
                "ok": False,
                "code": "GPU_RUNTIME_INSTALL_FAILED",
                "message": (
                    f"{last_error}。文件已下载到本地缓存，可重试安装或改用「手动下载」选择已下好的 .whl。"
                ),
                "detail": last_detail,
                "suggestManual": True,
                "localPaths": local_paths,
            }

    # Known CUDA wheels already tried via direct HTTP on every mirror. pip -i
    # rarely does better and used to burn a full 30 minutes per source.
    if direct_attempted:
        return {
            "ok": False,
            "code": "GPU_RUNTIME_INSTALL_FAILED",
            "message": (
                (last_error or "所有镜像直链下载均失败或过慢")
                + "。请改用「手动下载」：浏览器下载 .whl 后本地安装（可用下载器断点续传）。"
            ),
            "detail": last_detail,
            "suggestManual": True,
        }

    for mirror_url, host in mirrors:
        emit(
            {
                "type": "progress",
                "stage": "download",
                "percent": 18,
                "detail": f"使用镜像 {host} 通过 pip 下载 CUDA 12 组件…",
                "mirror": mirror_url,
                "totalBytes": hint_total,
            }
        )
        cmd = [
            sys.executable,
            "-u",
            "-m",
            "pip",
            "install",
            "--upgrade",
            "--progress-bar",
            "on",
            "-i",
            mirror_url,
            "--trusted-host",
            host,
            *packages,
        ]
        _log.info("ensure_gpu_runtime: %s", " ".join(cmd))
        env = os.environ.copy()
        env["PYTHONUNBUFFERED"] = "1"
        env.setdefault("PIP_DEFAULT_TIMEOUT", "120")
        env.setdefault("PIP_PROGRESS_BAR", "on")
        try:
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                env=env,
                bufsize=0,
            )
        except Exception as err:
            last_error = str(err)
            last_detail = str(err)
            continue

        lines: list[str] = []
        started_at = time.monotonic()
        stop_hb = threading.Event()
        meter = {
            "downloaded": 0,
            "total": hint_total,
            "speed": 0.0,
            "last_emit": 0.0,
            "last_bytes_at": time.monotonic(),
            "last_bytes": 0,
            "file_total": 0,
            "file_done": 0,
            "completed_files": 0,
            "file_committed": False,
            "pip_seen": False,
            "wheel_sizes": {},
            "last_progress_at": time.monotonic(),
            "stalled": False,
            "stall_reason": "",
            "session_start_at": time.monotonic(),
            "session_start_bytes": 0,
        }
        nvidia_root = Path(sys.prefix) / "Lib" / "site-packages" / "nvidia"
        nvidia_baseline = _dir_nbytes(nvidia_root)
        watch_roots = _refresh_pip_watch_roots(nvidia_root, [])
        root_baseline: dict[str, int] = {}
        for root in watch_roots:
            try:
                root_baseline[str(root.resolve()).lower()] = _dir_nbytes(root)
            except Exception:
                root_baseline[str(root).lower()] = _dir_nbytes(root)

        def _fallback_grown() -> int:
            nonlocal watch_roots
            watch_roots = _refresh_pip_watch_roots(nvidia_root, watch_roots)
            best_g = 0
            for root in watch_roots:
                try:
                    key = str(root.resolve()).lower()
                except Exception:
                    key = str(root).lower()
                cur = _dir_nbytes(root)
                base = root_baseline.get(key)
                if base is None:
                    root_baseline[key] = 0
                    base = 0
                best_g = max(best_g, max(0, cur - base))
            nvidia_grown = max(0, _dir_nbytes(nvidia_root) - nvidia_baseline)
            return max(best_g, nvidia_grown)

        def _recompute_total() -> int:
            wheels = meter["wheel_sizes"]
            announced = int(sum(int(v) for v in wheels.values())) if wheels else 0
            wheel_blob = " ".join(str(k).lower().replace("-", "_") for k in wheels)
            remaining = 0
            for pkg in packages:
                token = str(pkg).lower().replace("-", "_")
                if token and token in wheel_blob:
                    continue
                remaining += int(
                    CUDA12_SIZE_HINT_BYTES.get(pkg)
                    or CUDA13_SIZE_HINT_BYTES.get(pkg)
                    or (80 * 1024 * 1024)
                )
            total = max(int(hint_total or 0), announced + remaining, announced)
            cur_file = int(meter["file_total"] or 0)
            total = max(total, int(meter["completed_files"] or 0) + cur_file)
            meter["total"] = total
            return total

        def _emit_download(detail: str, *, force: bool = False) -> None:
            now = time.monotonic()
            if not force and now - meter["last_emit"] < 0.25:
                return
            meter["last_emit"] = now
            elapsed = now - started_at
            pip_downloaded = int(meter["downloaded"] or 0)
            if meter["pip_seen"] and pip_downloaded > 0:
                downloaded = pip_downloaded
            else:
                downloaded = max(pip_downloaded, _fallback_grown())
                if downloaded > pip_downloaded:
                    meter["downloaded"] = downloaded
            total = _recompute_total()
            if total > 0 and downloaded > 0:
                soft_pct = min(80, 18 + int(62 * min(1.0, downloaded / total)))
            else:
                soft_pct = min(80, 18 + int(elapsed / 12))
            dt = max(1e-3, now - float(meter["last_bytes_at"]))
            prev = int(meter["last_bytes"] or 0)
            if downloaded >= prev:
                instant = (downloaded - prev) / dt
                if 0 < instant <= 100 * 1024 * 1024:
                    prev_speed = float(meter["speed"] or 0)
                    meter["speed"] = instant if prev_speed <= 0 else (prev_speed * 0.6 + instant * 0.4)
            if downloaded > prev:
                meter["last_progress_at"] = now
            meter["last_bytes"] = downloaded
            meter["last_bytes_at"] = now
            speed = float(meter["speed"] or 0)
            if speed <= 0 and downloaded > 0 and elapsed > 0.8:
                speed = downloaded / elapsed
            emit(
                {
                    "type": "progress",
                    "stage": "download",
                    "percent": soft_pct,
                    "detail": detail,
                    "mirror": mirror_url,
                    "downloadedBytes": int(downloaded),
                    "totalBytes": int(total if total > 0 else hint_total),
                    "bytesPerSecond": round(max(0.0, speed), 1),
                    "suggestManual": bool(
                        speed > 0 and speed < 80_000 and downloaded > 2 * 1024 * 1024
                    ),
                }
            )

        def _heartbeat() -> None:
            while not stop_hb.wait(1.0):
                elapsed = time.monotonic() - started_at
                now = time.monotonic()
                downloaded = int(meter["downloaded"] or 0)
                session_bytes = max(0, downloaded - int(meter["session_start_bytes"] or 0))
                try:
                    from .pip_mirror_util import transfer_should_abort

                    reason = transfer_should_abort(
                        elapsed_sec=now - float(meter["session_start_at"]),
                        session_bytes=session_bytes,
                        last_progress_age_sec=now - float(meter["last_progress_at"]),
                    )
                except Exception:
                    reason = None
                    # Fallback if helper unavailable.
                    stall_limit = 60.0 if meter["pip_seen"] or downloaded > 0 else 90.0
                    if (now - float(meter["last_progress_at"])) > stall_limit or elapsed > 480:
                        reason = "STALL: 下载停滞或超时"
                if reason:
                    meter["stalled"] = True
                    meter["stall_reason"] = reason
                    try:
                        proc.kill()
                    except Exception:
                        pass
                    return
                if not meter["pip_seen"]:
                    grown = _fallback_grown()
                    # Only treat real growth (>= 256 KiB) as progress — dir-scan jitter
                    # used to reset the stall timer and burn the full 30 min timeout.
                    if grown >= int(meter["downloaded"] or 0) + 256 * 1024:
                        meter["downloaded"] = grown
                        meter["last_progress_at"] = time.monotonic()
                _emit_download(
                    f"镜像 {host} 下载中…（已等待 {int(elapsed)} 秒）",
                    force=True,
                )

        hb_thread = threading.Thread(target=_heartbeat, name=f"gpu-pip-hb-{host}", daemon=True)
        hb_thread.start()
        returncode = 1
        try:
            assert proc.stdout is not None
            buf = b""
            while True:
                chunk = proc.stdout.read(512)
                if not chunk:
                    break
                if meter["stalled"]:
                    break
                buf += chunk
                while b"\n" in buf or b"\r" in buf:
                    if b"\r" in buf and (b"\n" not in buf or buf.find(b"\r") < buf.find(b"\n")):
                        part, buf = buf.split(b"\r", 1)
                    else:
                        part, buf = buf.split(b"\n", 1)
                    line = part.decode("utf-8", errors="replace").strip()
                    if not line:
                        continue
                    lines.append(line)
                    if len(lines) > 80:
                        lines = lines[-80:]
                    stats = _parse_pip_byte_progress(line)
                    if stats:
                        wheel = str(stats.get("wheel") or "").strip()
                        if wheel and stats.get("total") is not None and stats.get("downloaded") is None:
                            if meter["file_total"] and not meter["file_committed"]:
                                meter["completed_files"] = int(meter["completed_files"]) + int(
                                    meter["file_total"]
                                )
                                meter["file_committed"] = True
                            meter["wheel_sizes"][wheel] = int(stats["total"])
                            meter["file_total"] = int(stats["total"])
                            meter["file_done"] = 0
                            meter["file_committed"] = False
                            meter["pip_seen"] = True
                            # New file announcement counts as progress once.
                            meter["last_progress_at"] = time.monotonic()
                            _recompute_total()
                        if stats.get("downloaded") is not None:
                            file_done = int(stats["downloaded"])
                            file_total = int(stats.get("total") or meter["file_total"] or 0)
                            if (
                                meter["file_done"] > 0
                                and file_done + 1024 * 1024 < meter["file_done"]
                                and file_total > 0
                            ):
                                if meter["file_total"] and not meter["file_committed"]:
                                    meter["completed_files"] = int(meter["completed_files"]) + int(
                                        meter["file_total"]
                                    )
                                meter["file_committed"] = False
                            prev_done = int(meter["file_done"] or 0)
                            meter["file_done"] = file_done
                            if file_total > 0:
                                meter["file_total"] = file_total
                            meter["pip_seen"] = True
                            # Only real byte growth resets the stall timer (pip redraws
                            # the same "N/M MB" line forever on a hung transfer).
                            if file_done > prev_done:
                                meter["last_progress_at"] = time.monotonic()
                            if file_total > 0 and file_done >= file_total:
                                if not meter["file_committed"]:
                                    meter["completed_files"] = int(meter["completed_files"]) + file_total
                                    meter["file_committed"] = True
                                meter["downloaded"] = int(meter["completed_files"])
                            else:
                                meter["downloaded"] = int(meter["completed_files"]) + file_done
                            _recompute_total()
                        elif stats.get("total") is not None and not wheel:
                            announced = int(stats["total"])
                            meter["total"] = max(int(meter["total"] or 0), hint_total, announced)
                        if stats.get("speed") is not None:
                            spd = float(stats["speed"])
                            if 0 < spd <= 100 * 1024 * 1024:
                                meter["speed"] = spd
                    detail = _format_pip_progress_line(line, host)
                    if detail or stats:
                        _emit_download(detail or f"镜像 {host} 下载中…")
                    if time.monotonic() - started_at > 480:
                        try:
                            proc.kill()
                        except Exception:
                            pass
                        last_error = "STALL: 单镜像超过 8 分钟上限"
                        last_detail = "\n".join(lines[-20:])
                        meter["stalled"] = True
                        meter["stall_reason"] = last_error
                        break
            returncode = proc.wait(timeout=30)
        except Exception as err:
            try:
                proc.kill()
            except Exception:
                pass
            last_error = str(err)
            last_detail = "\n".join(lines[-20:]) if lines else str(err)
            continue
        finally:
            stop_hb.set()
            try:
                hb_thread.join(timeout=1.0)
            except Exception:
                pass

        log_tail = "\n".join(lines[-30:]).strip()
        if meter["stalled"]:
            last_error = str(meter.get("stall_reason") or f"STALL: 下载停滞（镜像 {host}）")
            last_detail = log_tail[-1200:]
            emit(
                {
                    "type": "progress",
                    "stage": "download",
                    "percent": 18,
                    "detail": f"镜像 {host} 过慢/停滞，自动切换下一源…",
                    "mirror": mirror_url,
                    "downloadedBytes": int(meter["downloaded"] or 0),
                    "totalBytes": int(meter["total"] or hint_total),
                    "bytesPerSecond": 0,
                    "suggestManual": True,
                }
            )
            continue

        if returncode == 0:
            final_bytes = max(int(meter["downloaded"] or 0), _fallback_grown(), int(hint_total or 0))
            emit(
                {
                    "type": "progress",
                    "stage": "download",
                    "percent": 82,
                    "detail": f"镜像 {host} 安装完成",
                    "mirror": mirror_url,
                    "downloadedBytes": final_bytes,
                    "totalBytes": final_bytes,
                    "bytesPerSecond": 0,
                }
            )
            return {
                "ok": True,
                "mirror": mirror_url,
                "host": host,
                "logTail": log_tail[-500:],
            }

        last_error = f"pip 安装 GPU 支持失败（exit {returncode}，镜像 {host}）"
        last_detail = log_tail[-1200:]
        deny = bool(
            re.search(
                r"(?:HTTP\s*error\s*403|403\s*Client\s*Error|Forbidden\s+for\s+url|STALL:)",
                last_detail,
                re.I,
            )
        )
        try:
            if deny and note_mirror_denied:
                note_mirror_denied(host)
        except Exception:
            pass
        emit(
            {
                "type": "progress",
                "stage": "download",
                "percent": 18,
                "detail": (
                    f"镜像 {host} 返回 403，自动切换下一源…"
                    if deny
                    else f"镜像 {host} 失败，自动切换下一源…"
                ),
                "mirror": mirror_url,
                "downloadedBytes": int(meter["downloaded"] or 0),
                "totalBytes": int(meter["total"] or hint_total),
                "bytesPerSecond": 0,
                "suggestManual": True,
            }
        )

    return {
        "ok": False,
        "code": "GPU_RUNTIME_INSTALL_FAILED",
        "message": (
            (last_error or "所有国内镜像均无法安装 CUDA 12 支持组件")
            + "。可改用「手动下载」用浏览器下载 .whl 后本地安装。"
        ),
        "detail": last_detail,
        "suggestManual": True,
    }


def _parse_pip_byte_progress(line: str) -> dict[str, int | float | str] | None:
    """
    Extract downloaded / total / speed from pip progress text.

    Examples:
      Downloading nvidia_cublas_cu12-....whl (595.3 MB)
      123.4/567.8 MB 12.3 MB/s
      45%|████| 123.4M/360.1M [00:10<00:20, 12.3MB/s]
    """
    text = str(line or "").strip()
    if not text:
        return None
    # Strip ANSI
    text = re.sub(r"\x1b\[[0-9;]*[A-Za-z]", "", text)
    out: dict[str, int | float | str] = {}

    m_ann = re.search(
        r"Downloading\s+(\S+)\s+\(([\d.]+)\s*(GiB|MiB|KiB|GB|MB|KB|B)\)",
        text,
        re.I,
    )
    if m_ann:
        out["wheel"] = m_ann.group(1)
        out["total"] = _unit_to_bytes(float(m_ann.group(2)), m_ann.group(3))

    # 123.4/567.8 MB  OR  123.4MB/567.8MB  OR  123.4M/567.8M
    m_frac = re.search(
        r"([\d.]+)\s*(GiB|MiB|KiB|GB|MB|KB|B|G|M|K)?\s*/\s*([\d.]+)\s*(GiB|MiB|KiB|GB|MB|KB|B|G|M|K)\b",
        text,
        re.I,
    )
    if m_frac:
        unit_done = m_frac.group(2) or m_frac.group(4)
        out["downloaded"] = _unit_to_bytes(float(m_frac.group(1)), unit_done)
        out["total"] = _unit_to_bytes(float(m_frac.group(3)), m_frac.group(4))

    m_speed = re.search(
        r"([\d.]+)\s*(GiB|MiB|KiB|GB|MB|KB|B|G|M|K)\s*/\s*s\b",
        text,
        re.I,
    )
    if not m_speed:
        m_speed = re.search(
            r"([\d.]+)\s*(GiB|MiB|KiB|GB|MB|KB|B|G|M|K)/s\b",
            text,
            re.I,
        )
    if m_speed:
        out["speed"] = float(_unit_to_bytes(float(m_speed.group(1)), m_speed.group(2)))

    return out or None


def _unit_to_bytes(value: float, unit: str) -> int:
    u = str(unit or "B").strip().upper()
    if u in ("G", "GB", "GIB"):
        return int(value * 1024 * 1024 * 1024)
    if u in ("M", "MB", "MIB"):
        return int(value * 1024 * 1024)
    if u in ("K", "KB", "KIB"):
        return int(value * 1024)
    return int(value)

def _format_pip_progress_line(line: str, host: str) -> str:
    text = str(line or "").strip()
    if not text:
        return ""
    # Drop pure progress-bar noise; byte parser already handled counters.
    if re.fullmatch(r"[━\-█▌\| /.\d%A-Za-z]+", text) and "/" in text:
        return ""
    lower = text.lower()
    if lower.startswith("looking in indexes"):
        return f"连接镜像 {host}…"
    if "requirement already satisfied" in lower:
        pkg = text.split(":", 1)[-1].strip() if ":" in text else text
        return f"已满足：{pkg[:80]}"
    if lower.startswith("collecting "):
        return f"解析依赖：{text[10:].strip()[:100]}"
    if "downloading" in lower:
        return text[:160]
    if lower.startswith("installing collected") or "successfully installed" in lower:
        return text[:160]
    if "error" in lower or "failed" in lower:
        return text[:160]
    if any(k in lower for k in ("using cached", "preparing metadata", "building wheel", "built ")):
        return text[:160]
    return ""

